package com.bank.slab.service;

import java.util.logging.Logger;

// Finds the ceiling slab: smallest threshold >= requested amount.
public class SlabService {
    private static final Logger log = Logger.getLogger(SlabService.class.getName());

    public int ceilingSlab(int[] slabs, int amount) {
        int n = slabs.length;
        if (amount > slabs[n - 1]) {
            log.warning(() -> "Amount " + amount + " above all slabs; no ceiling");
            return -1; // no slab at or above the amount
        }
        int start = 0, end = n - 1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (amount < slabs[mid]) end = mid - 1;
            else if (amount > slabs[mid]) start = mid + 1;
            else return slabs[mid]; // exact slab boundary
        }
        final int ceil = slabs[start]; // start lands on the ceiling
        log.info(() -> "Ceiling slab for amount " + amount + " is " + ceil);
        return ceil;
    }
}
